import os, re

def load_session():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    basename = os.path.basename(d) + '.jsonl'
    fpath = d + '/' + basename
    t = open(fpath).read()
    lines = t.split('\n')

    grids = {}
    i = 0
    key = None
    nrows = 0
    for line in lines:
        if key is None:
            key = None
            continue
        if not line.strip() or len(line.split()) == 0:
            if key and nrows > 0:
                grids[key] = grids[key].pop()  # remove incomplete
            key = None
            nrows = 0
            continue
        line = line.strip()
        if key is not None:
            rows = line.split()
            if len(rows) > 0 and all(x.isdigit() for x in rows):
                if nrows == 0:
                    grid = []
                grid.append([int(x) for x in rows])
                nrows += 1
                if len(grid) > 1:
                    grid = grid.pop()
                    grids[key] = grid
            elif nrows > 0:
                # Check if this is a new section header
                match = re.match(r'(Demo pair \d+ (?:input|output)|Test input)', line)
                if match:
                    prev_key = key
                    key = match.group(1)
                else:
                    grids[key] = grid
                grid = None

    return grids

